pseudocode:
1. if (edges.length !== n - 1) return false
2. adj = buildAdjacencyList(n, edges)
3. visited = new Set()
4. queue = [0]
5. visited.add(0)
6. while (queue.length > 0) {
7.   curr = queue.shift()
8.   for (neighbor of adj[curr]) {
9.     if (!visited.has(neighbor)) {
10.      visited.add(neighbor)
11.      queue.push(neighbor)
12.    }
13.  }
14. }
15. return visited.size === n
